/**
 * An anchored, non-modal surface for rich content (`design/components/popover.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/popover.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import {
  createMemo,
  createUniqueId,
  mergeProps,
  onCleanup,
  onMount,
  useContext,
  type JSX,
} from 'solid-js'
import { Portal } from 'solid-js/web'

import * as zag from '@zag-js/popover'
import { normalizeProps } from '@zag-js/solid'

import {
  BORROWED,
  agentMember,
  anchorProps,
  claimSlot,
  createDerived,
  elementRef,
  mergeParts,
  provide,
  scope,
  syncTriggerAnchor,
  useDirection,
  useMachine,
  useMediaQuery,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/overlays/popover.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import triggerAnchor from '@polymorph/recipes/overlays/trigger-anchor.module.css'

export type PopoverAlign = NonNullable<PopoverProps['align']>

export type PopoverSide = NonNullable<PopoverProps['side']>

export interface PopoverProps {
  align?: 'start' | 'center' | 'end'
  children: JSX.Element
  defaultOpen?: boolean
  /**
   * The panel's accessible name; required on purpose.
   */
  label: string
  onOpenChange?: (open: boolean) => void
  open?: boolean
  /**
   * `'auto'` stays anchored at every width, because Popover is non-modal by contract and a
   * default must not change that on phones only. `'sheet'` is the app's opt-in: unchanged above
   * `30rem`, and a modal bottom sheet below it (the sheet presentation,
   * `design/components/README.md`), as the spec states.
   */
  presentation?: 'auto' | 'sheet'
  side?: 'bottom' | 'top' | 'right' | 'left'
  trigger: JSX.Element
}

/** An anchored, non-modal surface for rich content. */
export default function Popover(given: PopoverProps): JSX.Element {
  const props = mergeProps(
    { side: 'bottom', align: 'start', presentation: 'auto' } as Defaults<
      PopoverProps,
      'side' | 'align' | 'presentation'
    >,
    claimSlot(given),
  )
  const lender = useContext(BORROWED)
  return scope(() => {
    provide(BORROWED, undefined)
    const uid = createUniqueId()
    const anchor = elementRef<HTMLElement>()
    const panel = elementRef<HTMLElement>()
    const scrim = elementRef<HTMLElement>()
    const sheetPanel = elementRef<HTMLElement>()
    const phone = useMediaQuery('phone')
    const sheeting = createDerived(() => props.presentation === 'sheet' && phone())
    const documentDirection = useDirection()
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          open: props.open,
          defaultOpen: props.defaultOpen,
          modal: sheeting.value,
          positioning: {
            placement: props.align === 'center' ? props.side : `${props.side}-${props.align}`,
            offset: { mainAxis: 4 },
          },
          onOpenChange: (details) => {
            props.onOpenChange?.(details.open)
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const present = usePresence(
      () => api.value.open && !sheeting.value,
      () => panel.value,
    )
    const sheetPresent = usePresence(
      () => api.value.open && sheeting.value,
      () => sheetPanel.value,
      'sheet.panel',
      { sheetSide: 'bottom' },
    )
    const scrimPresent = usePresence(
      () => api.value.open && sheeting.value,
      () => scrim.value,
      'dialog.scrim',
    )
    const effect1 = () => {
      syncTriggerAnchor(anchor.value, api.value.getTriggerProps(), api.value.open)
    }
    watchEffect(
      createMemo(() => api.value.open),
      effect1,
      true,
    )
    const effect2 = () => {
      void (lender && (lender.element = () => panel.value ?? sheetPanel.value))
    }
    onMount(effect2)
    let release3: (() => void) | undefined
    const effect3 = () => {
      release3?.()
      const ran = lender
        ? () => {}
        : agentMember({
            member: 'Popover',
            element: () => panel.value ?? sheetPanel.value,
            state: () => ({ open: api.value.open }),
            actions: { close: () => api.value.open && api.value.setOpen(false) },
          })
      release3 = () => {
        ran()
      }
    }
    onMount(effect3)
    onCleanup(() => release3?.())
    return (
      <>
        {/* trigger */}
        <span
          {...mergeParts(anchorProps(api.value.getTriggerProps()), { class: triggerAnchor.anchor })}
          ref={anchor.attach}
        >
          {props.trigger}
        </span>
        <Portal>
          {present() ? (
            <div {...mergeParts(api.value.getPositionerProps())}>
              {/* panel */}
              <div
                {...mergeParts(api.value.getContentProps(), {
                  class: styles.panel,
                  style: { '--radix-popover-content-transform-origin': 'var(--transform-origin)' },
                  hidden: undefined,
                  'aria-labelledby': undefined,
                  'aria-describedby': undefined,
                  'aria-label': props.label,
                  'data-member': 'popover',
                })}
                ref={panel.attach}
              >
                {props.children}
              </div>
            </div>
          ) : null}
          {scrimPresent() ? (
            <div
              class={sheet.scrim}
              data-state={api.value.open ? 'open' : 'closed'}
              ref={scrim.attach}
            />
          ) : null}
          {sheetPresent() ? (
            <div class={sheet.positioner}>
              <div
                {...mergeParts(api.value.getContentProps(), {
                  class: sheet.panel,
                  hidden: undefined,
                  'aria-labelledby': undefined,
                  'aria-describedby': undefined,
                  'aria-label': props.label,
                  'data-presentation': 'sheet',
                })}
                ref={sheetPanel.attach}
              >
                {/* panel */}
                <div class={styles.sheetBody} data-member="popover">
                  {props.children}
                </div>
              </div>
            </div>
          ) : null}
        </Portal>
      </>
    )
  })
}
